const body = $input.first().json;

const agente = body.agente?.trim();
const intencao = body.intencao?.trim();
const content = body.content?.trim();
const file = body.file?.trim();

if (!agente || !intencao || !content) {
  throw new Error(`Campos obrigatórios ausentes: agente=${agente}, intencao=${intencao}`);
}

return [{
  json: { agente, intencao, content, file }
}];

const item = $input.first().json;

return [{
  json: { text: item.content },
  binary: {
    data: {
      data: Buffer.from(item.content, 'utf-8').toString('base64'),
      mimeType: 'text/plain',
      fileName: item.file || 'chunk.md'
    }
  }
}];
